<?php use common\widgets\Alert;use yii\helpers\{Html,Url};$this->title='Pengaturan Prodi';?>
<?=Alert::widget()?><div class="d-flex align-items-baseline mb-3"><h1 class="mb-0 mr-2">Setting</h1><span class="text-muted">Setting Program Studi</span></div><div class="card card-warning card-outline"><div class="card-body"><?=Html::beginForm(['index'],'get',['id'=>'program-setting-filter'])?><div class="row"><div class="col-md-6"><label class="text-warning">Periode</label><?=Html::dropDownList('academic_period',$academic_period,$periods,['class'=>'form-control'])?></div><div class="col-md-6"><label class="text-warning">Unit/Prodi</label><?=Html::dropDownList('university_id',$university_id,$universities,['class'=>'form-control'])?></div></div><?=Html::endForm()?></div></div>
<div class="card card-success card-outline"><div class="card-body table-responsive p-2"><table class="table table-bordered table-striped mb-0"><thead class="thead-dark"><tr><th style="min-width:300px">Program Studi</th><th style="width:145px">Kurikulum<br>Mahasiswa Baru</th><?php foreach(backend\models\StudyProgramSetting::booleanLabels() as $label):?><th class="text-center"><?=$label?></th><?php endforeach?><th style="width:80px">Aksi</th></tr></thead><tbody><?php $facultyId=null;foreach($programs as $program):?><?php if($facultyId!==$program->faculty_id):$facultyId=$program->faculty_id;?><tr class="font-weight-bold bg-light"><td><?=Html::encode($program->faculty->unit_name??'Tanpa Fakultas')?></td><td></td><?php foreach(backend\models\StudyProgramSetting::booleanAttributes() as $_):?><td></td><?php endforeach?><td></td></tr><?php endif;$setting=$settings[$program->id]??null;?><tr><td class="pl-4"><?=Html::encode($program->program_type.' - '.$program->name)?></td><td><?=Html::dropDownList('curriculum',$setting->new_student_curriculum_year_id??null,$curriculumYears,['class'=>'form-control form-control-sm js-program-curriculum','prompt'=>'','data-program'=>$program->id])?></td><?php foreach(backend\models\StudyProgramSetting::booleanAttributes() as $attribute):?><td class="text-center"><?=Html::checkbox($attribute,$setting?$setting->$attribute:false,['class'=>'js-program-toggle','data-program'=>$program->id,'data-attribute'=>$attribute])?></td><?php endforeach?><td class="text-center"><?php if($setting):?><?=Html::a('<i class="fas fa-edit"></i>',['update','id'=>$setting->id],['class'=>'btn btn-primary btn-sm'])?><?php else:?><?=Html::a('<i class="fas fa-plus"></i>',['create','study_program_id'=>$program->id,'academic_period'=>$academic_period],['class'=>'btn btn-success btn-sm'])?><?php endif?></td></tr><?php endforeach?></tbody></table></div></div>
<?php $toggle=Url::to(['toggle']);$curriculum=Url::to(['curriculum']);$js=<<<'JS'
$('#program-setting-filter select').on('change',function(){$('#program-setting-filter').submit();});
$(document).on('change','.js-program-toggle',function(){var el=this;$.post('__TOGGLE__?study_program_id='+$(el).data('program')+'&academic_period='+encodeURIComponent('__PERIOD__'),{_csrf:yii.getCsrfToken(),attribute:$(el).data('attribute'),value:el.checked?1:0}).done(function(r){if(r.success){Swal.fire({title:'Berhasil',text:r.message,icon:'success',timer:900,showConfirmButton:false});}else{el.checked=!el.checked;Swal.fire('Gagal',r.message,'error');}}).fail(function(){el.checked=!el.checked;Swal.fire('Gagal','Pengaturan tidak dapat disimpan.','error');});});
$(document).on('change','.js-program-curriculum',function(){var el=this;$.post('__CURRICULUM__?study_program_id='+$(el).data('program')+'&academic_period='+encodeURIComponent('__PERIOD__'),{_csrf:yii.getCsrfToken(),value:$(el).val()}).done(function(r){if(r.success){Swal.fire({title:'Berhasil',text:r.message,icon:'success',timer:900,showConfirmButton:false});}else{Swal.fire('Gagal',r.message,'error');}});});
JS;$this->registerJs(str_replace(['__TOGGLE__','__CURRICULUM__','__PERIOD__'],[$toggle,$curriculum,$academic_period],$js));?>
